package com.zenbyte.leave.controller;
import com.zenbyte.leave.dto.LoginRequest; import com.zenbyte.leave.entity.AppUser; import com.zenbyte.leave.service.AuthenticationService; import jakarta.servlet.http.*; import jakarta.validation.Valid; import org.springframework.security.authentication.*; import org.springframework.security.core.*; import org.springframework.security.core.context.*; import org.springframework.security.web.context.HttpSessionSecurityContextRepository; import org.springframework.security.web.context.SecurityContextRepository; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/auth") public class AuthController {
 private final AuthenticationManager am; private final AuthenticationService auth; private final SecurityContextRepository repo=new HttpSessionSecurityContextRepository();
 public AuthController(AuthenticationManager am,AuthenticationService auth){this.am=am;this.auth=auth;}
 @PostMapping("/login") public Map<String,Object> login(@Valid @RequestBody LoginRequest r,HttpServletRequest req,HttpServletResponse res){Authentication a=am.authenticate(new UsernamePasswordAuthenticationToken(r.username(),r.password()));SecurityContext c=SecurityContextHolder.createEmptyContext();c.setAuthentication(a);SecurityContextHolder.setContext(c);repo.saveContext(c,req,res);AppUser u=auth.current();Map<String,Object> out=new LinkedHashMap<>();out.put("role",u.getRole());out.put("username",u.getUsername());out.put("employeeId",u.getEmployee()==null?null:u.getEmployee().getEmployeeId());return out;}
 @GetMapping("/me") public Map<String,Object> me(){AppUser u=auth.current();Map<String,Object> out=new LinkedHashMap<>();out.put("authenticated",true);out.put("role",u.getRole());out.put("username",u.getUsername());out.put("employee",u.getEmployee()==null?null:Map.of("id",u.getEmployee().getId(),"employeeId",u.getEmployee().getEmployeeId(),"name",u.getEmployee().getName()));return out;}
}
